random.Random(42).shuffle(examples)
n=len(examples)
train_end=int(n*0.8); valid_end=int(n*0.9)
sets={'train':examples[:train_end],'valid':examples[train_end:valid_end],'test':examples[valid_end:]}
for name,rows in sets.items():
    with open(DATA/f'{name}.jsonl','w',encoding='utf-8') as f:
        for row in rows:
            f.write(json.dumps(row,ensure_ascii=False)+'\n')

print(f'Total={n} train={len(sets["train"])} valid={len(sets["valid"])} test={len(sets["test"])}')
